draw:
var r = p.r, g = p.gamma, kk = p.heat;
var eff = 1 - Math.pow(r, 1 - g);

// states in units where V2 = 1 and P1 = 1
var P1 = 1, V1 = r;
var P2 = Math.pow(r, g), V2 = 1;
var P3 = kk * P2, V3 = 1;
var P4 = kk, V4 = r;

var pad = 40;
var Pmax = P3 * 1.1, Vmax = r * 1.12;
var X = function (v) { return pad + (v / Vmax) * (W - pad - 14); };
var Y = function (pp) { return H - pad + 6 - (pp / Pmax) * (H - pad); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.2;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(pad, 8); ctx.lineTo(pad, Y(0)); ctx.lineTo(W - 8, Y(0));
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("P", pad - 26, 16);
ctx.textAlign = "right";
ctx.fillText("V", W - 8, Y(0) + 16);

function adiab(pa, va, vb, put) {
  var n = 40;
  for (var i = 0; i <= n; i++) {
    var v = va + (vb - va) * i / n;
    var pp = pa * Math.pow(va / v, g);
    if (i === 0) put(X(v), Y(pp), true); else put(X(v), Y(pp), false);
  }
}

// shade the enclosed area
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.6;
ctx.beginPath();
adiab(P1, V1, V2, function (x, y, first) { first ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
ctx.lineTo(X(V3), Y(P3));
adiab(P3, V3, V4, function (x, y) { ctx.lineTo(x, y); });
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// cycle outline
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
adiab(P1, V1, V2, function (x, y, first) { first ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
ctx.lineTo(X(V3), Y(P3));
adiab(P3, V3, V4, function (x, y) { ctx.lineTo(x, y); });
ctx.lineTo(X(V1), Y(P1));
ctx.stroke();

// animated dot, one second per leg
var per = 4, u = (t % per);
var dx, dy;
if (u < 1) { var v = V1 + (V2 - V1) * u; dx = X(v); dy = Y(P1 * Math.pow(V1 / v, g)); }
else if (u < 2) { dx = X(V2); dy = Y(P2 + (P3 - P2) * (u - 1)); }
else if (u < 3) { var v2 = V3 + (V4 - V3) * (u - 2); dx = X(v2); dy = Y(P3 * Math.pow(V3 / v2, g)); }
else { dx = X(V4); dy = Y(P4 + (P1 - P4) * (u - 3)); }
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(dx, dy, 5, 0, Math.PI * 2); ctx.fill();

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("1", X(V1) + 6, Y(P1) + 4);
ctx.fillText("4", X(V4) + 6, Y(P4) + 4);
ctx.textAlign = "right";
ctx.fillText("2", X(V2) - 6, Y(P2) + 4);
ctx.fillText("3", X(V3) - 6, Y(P3) + 4);
ctx.textAlign = "center";
ctx.fillStyle = C.figure;
ctx.fillText("adiabatic squeeze", (X(V1) + X(V2)) / 2, Y(P2) - 10);
ctx.fillText("burn, V fixed", X(V2) + 46, (Y(P2) + Y(P3)) / 2);
ctx.fillText("adiabatic push", (X(V3) + X(V4)) / 2, Y(P3 / 3) + 4);
ctx.fillText("exhaust, V fixed", X(V4) - 44, (Y(P4) + Y(P1)) / 2);

out.note = "compression ratio " + r.toFixed(1) + ", gamma " + g.toFixed(2) +
  " gives efficiency " + (eff * 100).toFixed(2) + "%  (shaded area is the net work)";
